// @ts-nocheck -- type-checked in the motion-film project, not here.
// Generated by scripts/sync-film.mjs from motion-film/src/scenes/SangeetScene.tsx. Edit it there, then run `npm run sync:film`.
import React from "react";
import { AbsoluteFill, useCurrentFrame } from "remotion";
import { Camera, ParallaxLayer, useCamera } from "../camera/Camera";
import { Stage } from "../stage/Stage";
import { SceneLighting } from "../stage/SceneLighting";
import { PaperBackground } from "../paper/PaperBackground";
import { GoldFrame } from "../ornaments/GoldFrame";
import { ShadowScreen, SideCurtain, SpotBeam, StringLights, Valance } from "../sets/CelebrationSets";
import { Character } from "../characters/Character";
import { people, wardrobe } from "../characters/cast";
import type { Outfit, Person, Pose } from "../characters/types";
import { Dhol } from "../props/CelebrationProps";
import { EventTitle } from "../kit/EventTitle";
import { Silhouette } from "../kit/Idle";
import { FallingPetals, GoldDust } from "../kit/Particles";
import { EASE, mix, prog } from "../kit/motion";
import { palette } from "../theme/palette";
import type { SceneProps } from "./types";
import { bi, whenBi } from "../data/i18n";

/*
 * Sangeet — a night stage. Plum & burgundy curtains under a scalloped gold valance, warm bulb
 * strings, a backlit shadow screen where dancers and a dhol player move to the beat, two soft
 * spotlights finding the couple, who dance centre stage in sync.
 */

const SVG: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <svg width={1080} height={1920} viewBox="0 0 1080 1920" style={{ position: "absolute", inset: 0, overflow: "visible" }}>
    {children}
  </svg>
);

const BEAT = 18; // frames per beat — locked to the 100 BPM soundtrack
const FEET = 1454;
const FIG = 610;
const R_X = 425;
const N_X = 655;

// shadow screen
const SX = 150;
const SY = 548;
const SW = 780;
const SH = 400;
const S_FEET = SY + SH - 6;
const S_FIG = 300;

// shadow-screen guests: no safa (its plume reads oddly in pure silhouette)
const plain = (o: Outfit): Outfit => (o.kind === "sherwani" ? { ...o, safa: undefined } : o);

type Dancer = { person: Person; outfit: Outfit; x: number; phase: number; kind: "dance" | "dhol" };
const DANCERS: Dancer[] = [
  { person: people.guestM2, outfit: plain(wardrobe.guestM2.festive), x: 250, phase: 0, kind: "dhol" },
  { person: people.guestF1, outfit: wardrobe.guestF1.festive, x: 395, phase: 0.6, kind: "dance" },
  { person: people.guestM1, outfit: plain(wardrobe.guestM1.festive), x: 545, phase: 2.2, kind: "dance" },
  { person: people.guestF2, outfit: wardrobe.guestF2.festive, x: 690, phase: 1.3, kind: "dance" },
  { person: people.guestF1, outfit: wardrobe.guestF1.festive, x: 835, phase: 3.0, kind: "dance" },
];

export const SangeetScene: React.FC<SceneProps> = ({ inv, dur, beatOffset = 0 }) => {
  const frame = useCurrentFrame();
  const ev = inv.events.sangeet;
  const titleAt = Math.min(128, dur - 180);

  const cam = useCamera([
    { frame: 0, scale: 1 },
    { frame: 90, scale: 1 },
    { frame: Math.max(210, titleAt + 80), scale: 1.05, y: 20 },
  ]);

  const open = prog(frame, 0, 56, EASE.inOut);
  const bulbs = prog(frame, 8, 44, EASE.inOut);
  const glow = prog(frame, 18, 30, EASE.out);
  const shadows = prog(frame, 32, 26, EASE.out);
  const beams = prog(frame, 44, 30, EASE.out);
  const energy = prog(frame, 76, 34, EASE.inOut);

  const ph = ((frame + beatOffset) / (BEAT * 2)) * Math.PI * 2; // one full cycle every two beats
  const u = 0.5 + 0.5 * Math.sin(ph); // 0..1 arm lift
  const bob = Math.sin(((frame + beatOffset) / BEAT) * Math.PI * 2) * 4 * energy;
  const sway = Math.sin(ph) * 1 * energy;

  // spotlight targets sweep in from the wings, then breathe gently on the couple
  const sweep = prog(frame, 44, 44, EASE.out);
  const tL = mix(-160, R_X + 10, sweep) + Math.sin(frame / 40) * 14 * sweep;
  const tR = mix(1240, N_X - 10, sweep) + Math.sin(frame / 44 + 1) * 14 * sweep;

  const rPose: Partial<Pose> = {
    lShoulder: mix(7, 26 + 96 * u, energy),
    lElbow: mix(-6, -18 - 50 * u, energy),
    rShoulder: mix(-7, -28 - 10 * u, energy),
    rElbow: mix(6, -46 + 10 * u, energy),
    headTilt: Math.sin(ph) * 3 * energy,
  };
  const nPose: Partial<Pose> = {
    rShoulder: mix(-7, -26 - 96 * u, energy),
    rElbow: mix(6, 18 + 50 * u, energy),
    lShoulder: mix(7, 28 + 10 * u, energy),
    lElbow: mix(-6, 46 - 10 * u, energy),
    headTilt: Math.sin(ph) * 3 * energy,
  };

  return (
    <Stage background="#231220">
      <Camera state={cam}>
        {/* BACKGROUND — deep plum back curtain */}
        <ParallaxLayer depth={0.15} blurStrength={0}>
          <SVG>
            <defs>
              <linearGradient id="sangeet-back" x1="0" y1="0" x2="1" y2="0" spreadMethod="repeat" gradientUnits="userSpaceOnUse" gradientTransform="scale(90 1)">
                <stop offset="0" stopColor="#3B1A33" />
                <stop offset="0.5" stopColor="#4E2344" />
                <stop offset="1" stopColor="#3B1A33" />
              </linearGradient>
              <linearGradient id="sangeet-shade" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0" stopColor="#140A12" stopOpacity={0.7} />
                <stop offset="0.3" stopColor="#140A12" stopOpacity={0} />
                <stop offset="0.8" stopColor="#140A12" stopOpacity={0} />
                <stop offset="1" stopColor="#140A12" stopOpacity={0.6} />
              </linearGradient>
            </defs>
            <rect width={1080} height={1920} fill="url(#sangeet-back)" />
            <rect width={1080} height={1520} fill="url(#sangeet-shade)" />
          </SVG>
          <PaperBackground stock="maroon" seed="sangeet" fibres={30} textureOnly />
        </ParallaxLayer>

        {/* SHADOW SCREEN with silhouettes dancing to the beat */}
        <ParallaxLayer depth={0.4} blurStrength={0}>
          <SVG>
            <ShadowScreen x={SX} y={SY} w={SW} h={SH} glow={glow} id="sangeet-screen" />
          </SVG>
          <div style={{ position: "absolute", left: SX, top: SY, width: SW, height: SH, overflow: "hidden", opacity: shadows }}>
            <Silhouette opacity={0.86}>
              {DANCERS.map((d, i) => {
                const p = ((frame + beatOffset) / (BEAT * 2)) * Math.PI * 2 + d.phase;
                const a = 0.5 + 0.5 * Math.sin(p);
                const hit = Math.sin(((frame + beatOffset) / BEAT) * Math.PI * 2 + d.phase);
                const pose: Partial<Pose> =
                  d.kind === "dhol"
                    ? { lShoulder: 34, lElbow: -84 + hit * 16, rShoulder: -34, rElbow: 84 + hit * 16, headTilt: hit * 3 }
                    : i % 2
                      ? { lShoulder: 30 + 110 * a, lElbow: -30 - 40 * a, rShoulder: -30 - 110 * (1 - a), rElbow: 30 + 40 * (1 - a), headTilt: Math.sin(p) * 5 }
                      : { lShoulder: 120 + 30 * a, lElbow: -60 + 30 * a, rShoulder: -120 - 30 * a, rElbow: 60 - 30 * a, headTilt: Math.sin(p) * 5 };
                const dx = d.x - SX;
                const bounce = Math.abs(Math.sin(((frame + beatOffset) / BEAT) * Math.PI + d.phase)) * -6;
                return (
                  <div
                    key={i}
                    style={{
                      position: "absolute",
                      left: dx - S_FIG * 0.2,
                      top: S_FEET - SY - S_FIG * 0.956 + bounce,
                      transform: `rotate(${Math.sin(p) * 3}deg)`,
                      transformOrigin: "50% 95%",
                    }}
                  >
                    <Character person={d.person} outfit={d.outfit} height={S_FIG} pose={pose} pins={false} />
                    {d.kind === "dhol" ? (
                      <svg width={S_FIG * 0.4} height={S_FIG} viewBox="0 0 120 300" style={{ position: "absolute", left: 0, top: 0, overflow: "visible" }}>
                        <g transform={`translate(60 ${0.56 * 300}) rotate(${hit * 2}) scale(0.62)`}>
                          <Dhol />
                        </g>
                        <path d="M40 115 Q60 150 80 170" stroke="#000" strokeWidth={3} fill="none" />
                      </svg>
                    ) : null}
                  </div>
                );
              })}
            </Silhouette>
          </div>
        </ParallaxLayer>

        {/* PROSCENIUM — valance and bulb strings */}
        <ParallaxLayer depth={0.6} blurStrength={0}>
          <SVG>
            <StringLights from={[60, 420]} to={[1020, 420]} sag={52} count={19} frame={frame} on={bulbs} seed={2} />
            <StringLights from={[60, 318]} to={[1020, 318]} sag={30} count={15} frame={frame} on={bulbs} seed={7} size={0.85} />
            <Valance y={212} color="#6E1F35" shade="#4A1226" swags={5} />
          </SVG>
        </ParallaxLayer>

        {/* STAGE — floor, spotlights, couple */}
        <ParallaxLayer depth={1}>
          <SVG>
            <defs>
              <linearGradient id="sangeet-floor" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0" stopColor="#3A2228" />
                <stop offset="1" stopColor="#24161A" />
              </linearGradient>
            </defs>
            <path d="M0 1416 L1080 1416 L1080 1536 L0 1536 Z" fill="url(#sangeet-floor)" />
            {new Array(9).fill(0).map((_, i) => (
              <path key={i} d={`M${120 * i + 60} 1416 L${(120 * i + 60 - 540) * 1.18 + 540} 1536`} stroke="#1C1014" strokeWidth={1.4} opacity={0.6} />
            ))}
            <rect x={0} y={1414} width={1080} height={3} fill={palette.gold} opacity={0.5} />
            <rect x={0} y={1534} width={1080} height={6} fill="url(#foil-h)" />
            <rect x={0} y={1540} width={1080} height={420} fill="#1B1116" />
            {/* footlights */}
            {new Array(9).fill(0).map((_, i) => {
              const x = 100 + i * 110;
              const a = bulbs * (0.8 + 0.2 * Math.sin(frame / 11 + i));
              return (
                <g key={i}>
                  <ellipse cx={x} cy={1528} rx={40} ry={16} fill="#FFD27A" opacity={0.16 * a} />
                  <path d={`M${x - 14} 1536 L${x + 14} 1536 L${x + 10} 1526 L${x - 10} 1526 Z`} fill={palette.goldDeep} />
                  <ellipse cx={x} cy={1526} rx={9} ry={3} fill="#FFE6A8" opacity={a} />
                </g>
              );
            })}
            <SpotBeam src={[150, 212]} dst={[tL, FEET]} spread={150} intensity={beams} id="sangeet-beam-l" />
            <SpotBeam src={[930, 212]} dst={[tR, FEET]} spread={150} intensity={beams} id="sangeet-beam-r" />
          </SVG>
          <GoldDust count={26} seed="sangeet-motes" area={[260, 700, 560, 760]} color="#FFE3B0" start={40} />
          {[
            { p: people.rishabh, o: wardrobe.rishabh.sangeet, x: R_X, pose: rPose, d: 0 },
            { p: people.nandita, o: wardrobe.nandita.sangeet, x: N_X, pose: nPose, d: 6 },
          ].map(({ p, o, x, pose, d }) => {
            const c = prog(frame, 58 + d, 30, EASE.out);
            return (
              <div
                key={p.id}
                style={{
                  position: "absolute",
                  left: x - FIG * 0.2,
                  top: FEET - FIG * 0.956 + bob + (1 - c) * 40,
                  opacity: c,
                  transform: `rotate(${sway}deg) scale(${0.96 + 0.04 * c})`,
                  transformOrigin: "50% 95.6%",
                }}
              >
                <Character person={p} outfit={o} height={FIG} pose={pose} />
              </div>
            );
          })}
        </ParallaxLayer>

        {/* SIDE CURTAINS — draw back to reveal the stage */}
        <ParallaxLayer depth={1.15} blurStrength={0}>
          <SVG>
            <SideCurtain side="left" open={0.35 + 0.65 * open} top={150} floor={1542} color="#7A2440" shade="#4A1226" id="sangeet-cl" />
            <SideCurtain side="right" open={0.35 + 0.65 * open} top={150} floor={1542} color="#7A2440" shade="#4A1226" id="sangeet-cr" />
            <rect x={0} y={0} width={1080} height={170} fill="#3A0E1E" />
            <rect x={0} y={164} width={1080} height={8} fill="url(#foil-h)" />
            {new Array(22).fill(0).map((_, i) => (
              <path key={i} d={`M${i * 50} 172 A25 25 0 0 0 ${i * 50 + 50} 172 Z`} fill="#3A0E1E" stroke={palette.gold} strokeWidth={1.4} />
            ))}
          </SVG>
        </ParallaxLayer>
        <FallingPetals count={16} seed="sangeet-petals" speed={0.6} start={-40} colors={[palette.rose, "#8C4A6E", palette.goldLight, palette.roseLight]} opacity={0.85} />
      </Camera>

      <SceneLighting
        warmth={0.2}
        keyX={50}
        keyY={55}
        spots={[
          { x: 50, y: 64, r: 34, color: "#FFC98A", intensity: 0.26 * beams },
          { x: 50, y: 39, r: 42, color: "#FFB866", intensity: 0.14 * glow },
        ]}
        vignette={0.55}
      />

      <AbsoluteFill>
        {frame >= titleAt ? (
          <EventTitle
            start={titleAt}
            kicker="Music & Dance"
            title={ev.title}
            lines={[whenBi(ev.date, ev.time), bi(ev.venue)]}
            top={1556}
            theme="light"
            titleSize={92}
          />
        ) : null}
      </AbsoluteFill>
      <GoldFrame />
    </Stage>
  );
};
